UPDATE public.civic_department_routes SET active = false, updated_at = now(), notes = notes || ' Superseded by the verified 2026-10-25 routing set (category naming aligned to the application taxonomy).' WHERE coverage_id = 'anantapur' AND active AND (category NOT IN ('roads','drainage','water','electricity','waste','sanitation','trees','parks','transport','buildings','other') OR receiving_office = 'Anantapuramu Municipal Corporation');